// Worker-backed e2e entry (make test-e2e-worker): the REAL Worker (src/worker.js: handle(), the Interview and LibraryStore Durable Objects) run by
// `wrangler dev` on workerd, local only. Two stand-ins, both offline: the Workers AI binding (the same fakes as dev/local-edge.mjs: talker, analyst,
// review model, embeddings; no speech, silent voice) and the Cloudflare Access key set (E2E_JWKS, generated by the test). Every other outbound
// fetch is refused, so a run never reaches Cloudflare, a model provider or any destination. Never deploy this file (dev/wrangler.e2e.jsonc only).
import worker, { Interview as RealInterview, LibraryStore as RealLibraryStore } from '../src/worker.js';
import { fakeTalker, fakeAnalyst } from './fake-interviewer.mjs';
import { fakeModel } from './fake-model.mjs';

const model = fakeModel();
const sse = text => new ReadableStream({ start(c) { const e = new TextEncoder(); for (const w of text.match(/\S+\s*/g) || []) c.enqueue(e.encode(`data: ${JSON.stringify({ response: w })}\n\n`)); c.enqueue(e.encode('data: [DONE]\n\n')); c.close(); } });
const fakeAI = env => ({
  toMarkdown: async f => ({ format: 'markdown', data: new TextDecoder().decode(await f.blob.arrayBuffer()) }),
  run: async (name, input) => {
    if (name === env.TALKER_MODEL && input.stream) return sse(fakeTalker(input.messages));
    if (name === env.ANALYST_MODEL && input.tools) return fakeAnalyst(input.messages);
    if (/smart-turn/.test(name)) return { is_complete: true, probability: 1 };
    if (input.audio) return { results: { channels: [{ alternatives: [{ transcript: '' }] }] } };
    if (input.text && input.speaker) return new Uint8Array(24000);
    if (Array.isArray(input.text)) return { data: [await model.embed(input.text[0])] };
    return { choices: [{ message: { content: await model.complete(input.messages) } }] };
  },
});

let jwks = null;
const realFetch = globalThis.fetch;
globalThis.fetch = async (url, init) => {
  const u = String(url instanceof Request ? url.url : url);
  if (jwks && u === jwks.url) return new Response(jwks.body, { headers: { 'Content-Type': 'application/json' } });
  void realFetch;
  throw new TypeError('e2e worker: outbound fetch refused (offline run)');
};
const withFakes = env => {
  if (!jwks && env.E2E_JWKS) jwks = { url: `https://${env.ACCESS_TEAM_DOMAIN}/cdn-cgi/access/certs`, body: String(env.E2E_JWKS) };
  return { ...env, AI: fakeAI(env) };
};

export class Interview extends RealInterview { constructor(ctx, env) { super(ctx, withFakes(env)); } }
export class LibraryStore extends RealLibraryStore { constructor(ctx, env) { super(ctx, withFakes(env)); } }
export default { fetch: (request, env, ctx) => worker.fetch(request, withFakes(env), ctx) };
